    opacity: 1;
    -webkit-transform: scale3d(0.475, 0.475, 0.475) translate3d(0, 60px, 0);
    transform: scale3d(0.475, 0.475, 0.475) translate3d(0, 60px, 0);
    -webkit-animation-timing-function: cubic-bezier(0.55, 0.055, 0.675, 0.19);
    animation-timing-function: cubic-bezier(0.55, 0.055, 0.675, 0.19);
  }

  to {
    opacity: 0;
    -webkit-transform: scale3d(0.1, 0.1, 0.1) translate3d(0, -2000px, 0);
    transform: scale3d(0.1, 0.1, 0.1) translate3d(0, -2000px, 0);
    -webkit-animation-timing-function: cubic-bezier(0.175, 0.885, 0.32, 1);
    animation-timing-function: cubic-bezier(0.175, 0.885, 0.32, 1);
  }
}

entries.sample:
page=canvas(size=(100mm,100mm),stylesheet="@laymesh/animate.css",background="#f6f7fb")
style {
rect {background-color:#0d6efd;border:1px solid #20332f}
text {background-color:#e9ecef;color:#212529;border:1px solid #adb5bd}
@keyframes catalog-fade {from{opacity:0;transform:translateY(5mm)}to{opacity:1;transform:translateY(0mm)}}
.sample {animation:catalog-fade 1s linear both;animation-delay:var(--animate-delay);}
}
item=page.add(rect(size=(40mm,25mm),class="sample"),anchor=center,target=page.center)
s=page.step(name="Preview",start="after-previous",hold=0s)
s.animate(item)

